def build(out):
    P = 'dlc11'
    out.pack(P, 'Конапты и апартаменты', 'Corporate Conapts & Studio Apartments')
    e = find(P, 'КОНАПТЫ И СТУДИИ')
    for i, (n, code, zone, info) in enumerate(CONAPTS, 1):
        out.add(P, 'property', n, cost=0, Group='Корпоративный конапт', Info=info, Lib=e['id'], Page=3 + (i > 5),
                Extra={'code': code, 'zone': zone, 'rent': '0', 'rentNote': 'предоставляется корпорацией', 'type': 'conapt', 'roll': str(i)})
    for i, (n, code, zone, info) in enumerate(STUDIOS, 1):
        out.add(P, 'property', n, cost=0, Group='Квартира-студия', Info=info, Lib=e['id'], Page=5 + (i > 5),
                Extra={'code': code, 'zone': zone, 'rent': '1500', 'type': 'studio', 'roll': str(i)})
    out.add(P, 'gear', 'Мебель: творческий порыв', cost=100, Group='Корпоративная мебель (за комнату)', Lib=e['id'], Page=7,
            Info='Минимальная обстановка: кровати — корпоративные казарменные излишки, стол с распродажи УНС, полки из ящиков из-под Киббла.')
    out.add(P, 'gear', 'Мебель: приятные апартаменты', cost=500, Group='Корпоративная мебель (за комнату)', Lib=e['id'], Page=7,
            Info='Кровать, комод, письменный стол или диван в каждой комнате. Начальный набор большинства конаптов и апартаментов; хозяин ничего не заменит, если сломаете.')
    out.add(P, 'gear', 'Мебель: желанный декор', cost=1000, Group='Корпоративная мебель (за комнату)', Lib=e['id'], Page=7,
            Info='Изголовье кровати, настоящий диван, исправная кухонная техника, оригинальные картины местных авторов.')
    out.add(P, 'gear', 'Настоящий кофе™ «Континентал Брендс»', cost=100, Group='Аксессуары для дома', Lib=e['id'], Page=7,
            Info='Вакуумная упаковка (полкило) растворимого кофе из настоящих зёрен; каждый «кирпичик» — до 24 чашек.')
    out.add(P, 'gear', 'УмнаяМикроволновка «Континентал Брендс»', cost=1000, Group='Аксессуары для дома', Lib=e['id'], Page=8,
            Info='Готовит горячую еду одним нажатием, 20 вкусовых профилей; раз в месяц заправляется Кибблом (входит в «Упаковку Киббла»). Заправка специалистом входит в любой образ лучше Киббла.')
    out.add(P, 'gear', 'К-Тех универсальная звукоизоляция', cost=1000, Group='Аксессуары для дома', Lib=e['id'], Page=8,
            Info='Цена за комнату. Невидимые панели за стенами: прослушивание через стену невозможно без киберусилителя слуха или аналога. Техники опаздывают и ждут чаевых от 20eb.')
    out.add(P, 'gear', 'Кендаши: душевая лейка «НапорТех»', cost=500, Group='Аксессуары для дома', Lib=e['id'], Page=8,
            Info='Гидрорежущий напор: 1 урон небронированной цели за каждые 20 минут под самым сильным напором; в броне, с тканекожей, подкожной бронёй и т. п. урона нет.')
    out.add(P, 'gear', 'Виртуальное барбекю от Сеготари', cost=500, Group='Аксессуары для дома', Lib=e['id'], Page=8,
            Info='Многопользовательская игра про гриль (готовить не научит) — зато завязалось много дружб.')
